:root {
  color-scheme: light;
  --ink: #1c1917;
  --muted: #57534e;
  --border: #d6d3d1;
  --accent: #0f766e;
  --bg: #fafaf9;
  --surface: #ffffff;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
}

#app {
  max-width: 40rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 1rem;
}

#note-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1rem;
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  background: var(--surface);
  margin-bottom: 1.5rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--muted);
}

input,
textarea {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 0.375rem;
  background: var(--surface);
  color: var(--ink);
}

input:focus-visible,
textarea:focus-visible,
button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.hint {
  margin: 0;
  font-size: 0.75rem;
  color: var(--muted);
}

#note-form > button {
  align-self: flex-start;
  font: inherit;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 0.375rem;
  background: var(--accent);
  color: white;
  cursor: pointer;
}

.search-row {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin-bottom: 1.5rem;
}

#results-line {
  margin: 0;
  font-size: 0.875rem;
  color: var(--muted);
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.note {
  padding: 0.875rem 1rem;
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  background: var(--surface);
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.25rem 0.75rem;
}

.note[aria-current='true'] {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.note-avatar {
  grid-row: 1 / span 2;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  object-fit: cover;
}

.note-heading {
  margin: 0;
  font-size: 1rem;
}

.note-title {
  font: inherit;
  font-weight: 600;
  color: var(--ink);
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-align: left;
}

.note-title:hover {
  color: var(--accent);
  text-decoration: underline;
}

.note-body {
  grid-column: 2;
  color: var(--ink);
  line-height: 1.4;
  word-wrap: break-word;
}

.note-body a {
  color: var(--accent);
}

